// Arma tres cosas con el mismo pedido:
//   · `mensaje`      → el aviso de Telegram para Sara
//   · `resumen`      → el desglose en texto plano (oportunidad, Telegram, correo 03)
//   · `resumenHtml`  → el mismo desglose en filas de tabla, CON la foto de cada
//                      prenda, que es lo que se ve dentro del correo 02
//
// POR QUE EL HTML LO COMPONE ESTE NODO Y NO LA PLANTILLA
// Una plantilla de correo de GHL no sabe recorrer los articulos de un pedido:
// no hay bucle ni condicional. Asi que el bucle se hace aqui y el resultado
// entero se guarda en el campo custom `resumen_pedido_html`, que la plantilla
// inserta con triple llave —en Handlebars, "sin escapar el HTML"—.
//
// `items[].name` ya viene con la talla pegada —"Vestido Asimetría Floral - M"—
// que es justo lo que hace falta para coger la prenda de la estanteria.

const pedido = $input.first().json;
const items = pedido.items || [];

// Datos del webhook de GHL. Si tu nodo se llama distinto, cambia 'Webhook'.
let delWebhook = {};
try { delWebhook = $('Webhook').first().json.body || $('Webhook').first().json || {}; } catch (e) { delWebhook = {}; }

const euros = (n) =>
  new Intl.NumberFormat('es-ES', { style: 'currency', currency: pedido.currency || 'EUR' }).format(n || 0);

// Todo lo que salga del pedido pasa por aqui antes de entrar en el HTML: un
// nombre de prenda con & o con comillas romperia la maqueta del correo.
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

// Una pasada por los articulos: de aqui salen las tres representaciones.
const piezas = items.map((it) => {
  const producto = it.product || {};
  const talla = it.price && it.price.name ? it.price.name : null;
  const nombre = it.name || producto.name || 'Artículo';
  // el nombre suele acabar en " - M": si ya lleva la talla, no se repite
  const yaLaLleva = talla && nombre.toLowerCase().endsWith('- ' + String(talla).toLowerCase());
  return {
    nombre,
    talla: yaLaLleva ? null : talla,
    cantidad: it.qty || it.quantity || 1,
    importe: it.price && typeof it.price.amount === 'number' ? it.price.amount : null,
    foto: producto.image || (producto.medias && producto.medias[0] && producto.medias[0].url) || '',
  };
});

const lineas = piezas.map((p) =>
  '· ' + p.nombre + (p.talla ? ' — talla ' + p.talla : '') + ' ×' + p.cantidad);

// Si el pedido llegara sin articulos, se avisa en vez de mandar un mensaje mudo:
// es preferible que Sara vea "no he podido leerlo" a que crea que no hay nada.
const cuerpo = lineas.length
  ? lineas.join('\n')
  : '⚠️ No he podido leer los artículos de este pedido. Míralo en Payments → Orders.';

const quien = [
  delWebhook.numero_pedido,
  pedido.contactSnapshot
    ? [pedido.contactSnapshot.firstName, pedido.contactSnapshot.lastName].filter(Boolean).join(' ')
    : null,
].filter(Boolean).join(' · ');

const mensaje = [
  'Pedido nuevo' + (quien ? ' ' + quien : ''),
  '',
  cuerpo,
  '',
  'Total ' + euros(pedido.amount),
].join('\n');

// --- El bloque que se ve dentro del correo -------------------------------
// Va como <table>, no como texto suelto: la triple llave se inserta dentro de
// una celda, y texto suelto entre celdas es HTML invalido —el editor de GHL lo
// recoloca fuera del bloque—. Estilos en linea, que es lo unico que respetan
// los clientes de correo. Sin <html> ni <body>: es un trozo, no un documento.
const SERIF = "Georgia, 'Times New Roman', serif";

const filas = piezas.map((p) => {
  const detalle = [
    p.talla ? 'Talla ' + esc(p.talla) : null,
    p.cantidad > 1 ? p.cantidad + ' uds' : null,
    p.importe != null ? euros(p.importe) : null,
  ].filter(Boolean).join(' &middot; ');
  // La celda de la foto se omite si la prenda no tiene: mejor una fila sin
  // imagen que un hueco con el icono de imagen rota.
  const celdaFoto = p.foto
    ? '<td width="72" style="width:72px; padding:0 0 16px 14px; vertical-align:top;">' +
        '<img src="' + esc(p.foto) + '" width="72" alt="" ' +
        'style="width:72px; height:auto; display:block; border:0;" /></td>'
    : '';
  return '<tr>' +
    '<td style="padding:0 0 16px 0; vertical-align:top;">' +
      '<p style="margin:0 0 3px 0; font-family:' + SERIF + '; font-size:15px; line-height:21px; color:#1E1B1A;">' +
        esc(p.nombre) + '</p>' +
      (detalle
        ? '<p style="margin:0; font-family:' + SERIF + '; font-size:12px; line-height:18px; color:#8A7E71;">' +
            detalle + '</p>'
        : '') +
    '</td>' + celdaFoto +
  '</tr>';
});

// El total cierra el bloque, con el mismo ancho de columnas para que la linea
// superior cruce toda la caja.
const filaTotal =
  '<tr><td colspan="2" style="padding:10px 0 0 0; border-top:1px solid rgba(30,27,26,.14);">' +
    '<p style="margin:0; font-family:' + SERIF + '; font-size:13px; color:#1E1B1A;">Total &nbsp;' +
      esc(euros(pedido.amount)) + '</p>' +
  '</td></tr>';

const resumenHtml = filas.length
  ? '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%">' +
      filas.join('') + filaTotal +
    '</table>'
  : '';

// El de texto plano va sin cabecera ni total: la plantilla ya los pone.
// Si no hay articulos se manda cadena vacia, para que el correo no ensene
// un aviso tecnico a la clienta.
const resumen = lineas.length ? lineas.join('\n') : '';

return [{
  json: {
    mensaje,
    resumen,
    resumenHtml,
    opportunityId: delWebhook.opportunityId || null,
    contactId: delWebhook.contactId || pedido.contactId || null,
    orderId: pedido._id,
    articulos: items.length,
  },
}];
